The WCET bound for an actor segment is the sum of the basic block instruction costs, the product of entry count and the fuel-check constant, the sum of call entry-point bounds, and the products of message sends with the promotion bound plus message receives with the decref bound.

```sol
fun WCET_Bound(
    instr_costs: array<int>,
    entry_count: int,
    fuel_check_const: int,
    call_bounds: array<int>,
    send_count: int,
    recv_count: int,
    prom_bound: int,
    decr_bound: int
) -> int {
    var total = 0;
    for i in 0 to instr_costs.size - 1 do
        total = total + instr_costs[i];
    end;
    total = total + entry_count * fuel_check_const;
    for i in 0 to call_bounds.size - 1 do
        total = total + call_bounds[i];
    end;
    total = total + send_count * prom_bound;
    total = total + recv_count * decr_bound;
    return total;
}
```

