})();
```

The `fill` function iterates through the keys of a `pending` object to identify which inputs need updating. For each key, it queries the document for elements matching the selector `[data-input="key"]`. If elements are found, it sets their `value` property to the corresponding pending data and dispatches a synthetic `input` event to trigger UI updates. If no elements are found, the function skips that key to avoid errors.

```fprisc
(function () {
  var pending = {};
  function fill() {
    Object.keys(pending).forEach(function (n) {
      var els = document.querySelectorAll('[data-input="' + n + '"]');
      if (!els.length) return;
      els.forEach(function (el) {
        el.value = pending[n];
        el.dispatchEvent(new Event('input'));
      });
      delete pending[n];
    });
  }
  document.addEventListener('live:set', function (e) {
    var vals = JSON.parse(e.detail);
    Object.keys(vals).forEach(function (n) { pending[n] = vals[n]; });
    fill();
  });
  new MutationObserver(fill).observe(document.getElementById('lv-root'), { childList: true, subtree: true });
})();
```

