  St rep boss k = st;
  _ = send rep (Ask me);
  r = receiveFrom me rep;  -- Changed from 'receive' to 'receiveFrom'
  Reply n = r;
  _ = drop r;
  _ = yield me;
  _ = case k % 8 == 0 of True -> Sys.sleepUs 100 | False -> Sys.sleepUs 0;
