-- Recursive function with certified measure
fn mvu_sum (lst: List Int) : Int =
  case lst of
    [] -> 0
    x::xs -> 1 + mvu_sum xs; -- Certified by measure
end;

-- Example of a lib/ module (unsafe, unbounded)
module "lib/json" unsafe;
use "core/";

-- Unbounded operation (e.g., parsing arbitrary input)
fn parse_json (input: String) : Json =
  -- Unbounded: input length not known at compile time
  parse_helper input;
end;
```

