```sol
fun connect-socket (path string) -> (socket socket)
{
  let s := new socket (AF_UNIX, SOCK_STREAM)
  let deadline := 5.0
  for i := 0 to int(deadline * 10)
  {
    try
      connect s path
    catch
      sleep 0.1
    end
  }
  return s
}

fun expect-output (s socket, pattern string, timeout real) -> (match match, remaining real)
{
  let end := now + timeout
  let buf := ""
  while now < end
  {
    let m := regex-search pattern buf
    if m != null
    then
      return (m, now - end)
    let chunk := recv s 65536
    if chunk == null
    then
      return (null, now - end)
    buf := buf + decode chunk
  }
  return (null, now - end)
}
```

The `expect` method waits for a specific regex pattern to appear in the serial console output within a defined timeout. It continuously reads data chunks from the socket and appends them to an internal buffer until the pattern is found or the timeout expires. If the pattern is found, it returns the match object; otherwise, it raises a failure exception.

```python
def expect(self, pattern, timeout, what):
    rx = re.compile(pattern)
    end = time.time() + timeout
    while time.time() < end:
        m = rx.search(self.buf)
        if m:
            self.buf = self.buf[m.end():]
            return m
        try:
            chunk = self.s.recv(65536)
        except socket.timeout:
            continue
        if not chunk:
            break
        self.buf += chunk.decode("utf-8", "replace")
    fail(f"timed out after {timeout}s waiting for {what}", self.buf)
```

