inc x = x + 1.
dbl x = x * 2.
mneg x = 0 - x.
addA a x = a + x.

refC i lim = if i > lim then 0 else (0 - (i + 1) * 2) + refC (i + 1) lim.

verdict n b = if b then print "ok {n}" else error "FAIL {n}".

