  v1 = Vec.map inc v0;
  v2 = Vec.map dbl v1;
  v3 = Vec.map mneg v2;
  (s1, _) = Vec.fold addA 0 v3;
  verdict "chain-sum" (s1 == refC 1 1000);
```

