```fpr
// Example of manifest parsing and permission gating logic
fn main() -> (sha: str, blob: bytes, perms: table) {
    let archive = read_archive();
    let manifest = parse_manifest(archive);

    // Verify SHA
    if sha_check(manifest.sha) != true {
        halt("SHA mismatch");
    }

    // Extract permissions and capability blob
    let perms = extract_perm_table(manifest);
    let blob = serialize_capability_blob(perms);

    // Gate permissions against allowed set
    if perm_gate(perms, allowed_set) != true {
        halt("Permission denied");
    }

    (manifest.sha, blob, perms)
}
```

