```sol
# Example: Using a compare-and-swap guard pattern
proc.myIdempotentOp = {
    local state = read("state.lock");
    if state == "locked" then
        return "already_executed";
    end
    lock("state.lock");
    try {
        execute_external_effect();
        write("state.lock", "locked");
    } finally {
        unlock("state.lock");
    }
    return "success";
