// Correct approach: yield via the actor machinery (e.g., send/spawn) to allow preemption.

import qos.hal;

fun unsafe_block() {
    // This is a hazard: it blocks/spins outside the fuel budget.
    // The WCET model cannot bound this duration.
    unsafe_hal_block_forever(); 
}
```

