```fprisc
Json = use "std/json";
main =
  text = "\{\"name\": \"test\", \"port\": 8080}";
  _ = (case Json.parse text of
      Err e -> print "ERR {e}"
    | Ok v -> print "port {Json.field \"port\" v |> Option.andThen Json.asInt}");
```

