```sol
// Example: Defining stack and slab sizes in the application manifest
// The system will use these values or fall back to machine defaults if omitted.
MANIFEST {
    APP "my_actor" {
        STACK_SIZE 512_K; // Override default 256 K
        SLAB_SIZE 128_K;  // Override default 256 K
        MSG_SLAB_SIZE 32_K; // Override default 64 K
    }
}
```

