  loop {
    if (msg) {
      // Simulate reading RBR until LSR.DR clears
      while (lsr.dr == 0) {
        rbr = read_reg(RBR);
      }
      rx_buffer.append(rbr);
      // Hand data downstream
      push_subscribers(rx_buffer);
    }
  }
}
```

