(async function boot() {
  const d = await j('/api/docs');
  DOCS = d.docs;
  $('#tabs').innerHTML = DOCS.map(x =>
    `<div class="tab" data-n="$\{esc(x.name)}">$\{esc(x.title)}</div>`).join('');
  document.querySelectorAll('.tab').forEach(t =>
    t.onclick = () => openDoc(t.dataset.n));
  loadRecent();
  const st = await j('/api/status');
  $('#stat').textContent = `heap $\{st.heap_kib} KiB · $\{st.preempts} preempts · $\{st.searches} searches served`;
  openDoc(DOCS[0].name);
})
```

