```sol
// Example of concurrency primitives in runtime/actors.c
actor wake(actor self, actor other) {
    // Uses atomics and SPSC channels to signal wake/IPI
    spsc_send(self, other, WAKE_EVENT);
}

// Example of allocator primitives in runtime/runtime.c
ptr alloc_actor(actor self, size_t size) {
    // Uses per-actor pools and named panics
