```sol
func readpty_print_events (dev: string) -> void
{
    // Open the pseudo-terminal device
    let fd = open(dev)
    if fd == null { return }

    // Loop to read and process events
    while true
    {
        // Read data from the pseudo-terminal
        let data = read(fd)
        if data == null { break }

        // Process data and emit event lines as per QOS convention
        for each char in data
        {
