fn buy(item-id: Int) -> { status: Int, price: Float } {
    let valid-items = ["flat white", "long black", "cheese toastie", "brownie", "carrot cake", "sparkling water"];
    let price-list = [5.0, 4.0, 9.0, 6.0, 7.0, 3.0];

