main =
  me = myself 0;
  fs = FS.serve (device "blk");
  ld = LD.serve fs;
  n = expectOk "replay" (LD.replay me ld);
  case n == 0 of
    True -> boot1 me ld
  | False -> boot2 me ld n.
```

