  (d1, dr) = Vec.dup d;
  pos0 = Vec.ges 0 d1;
  (p1, pr) = Vec.dup pos0;
  ds = Vec.axpb stride (0 - stride) (Vec.axpb 2 0 p1);
  _ = Vec.free d1;  # Error: d1 was never allocated
  Ax td1 (Vec.sar 16 (Vec.zipMul dist0 td2))
        (Vec.sar 16 (Vec.zipMul distE td3))
        ds (Vec.axpb 1 fbase p4).
```

