```sol
func sendKey(qcode)
  let json = {"execute": "input-send-event", "arguments": {"events": [{"type": "key", "data": {"down": true, "key": {"type": "qcode", "data": qcode}}}]}}
  let socket = open("qmp.sock", "rw")
