fn sol_cmd(cmd: string, args: map<string, string>) -> string:
    let msg = json_make_object()
    json_set_string(msg, "execute", cmd)
    if args.len() > 0:
        json_set_string(msg, "arguments", json_make_string(args))
    let result = qmp_execute(msg)
