fn renderScene(sceneVal : SceneValue) : (draws : DrawList, dynBytes : DynBytes) {
    // Host walks sceneVal read-only (no allocation here)
    let draws = walkScene(sceneVal)
    let dynBytes = constructResult(draws)
    return (draws, dynBytes)
}
```

