port = Json.field "port" (Json.parse text) |> Option.andThen Json.asInt;
deepX = Json.at ("nested" :: "deep" :: "x" :: Nil) (Json.parse text);
roundtrip = Json.equal text (Json.parse (Json.render (Json.parse text)));
```

