orbit k every x y vx vy | k <= 0 = [].
orbit k every x y vx vy =
  r2 = x * x + y * y;
  r3 = r2 * Num.sqrt r2;
  vx2 = vx - x / r3 * 0.02;
  vy2 = vy - y / r3 * 0.02;
