// The writeAtomic function ensures the redo journal and PID-stamped locks
// handle the commit safely, leaving the disk untouched on a panic.
txnAbort:
  writeAtomic {
    buffer <- "data";
    fsync;
    .done; // Marks deferred commands for at-least-once execution
  };
```

