To establish a TCP server connection, the `Tcp.listen` function is called with a local address and port number to obtain a listener object. This listener is then passed to `Tcp.serveOn` along with a running Poller and a server function to handle incoming connections. The server function receives the connection via `Stream.readerOn` and processes messages using `Stream.readLine`, responding to clients until they send "bye", at which point the connection is closed.

```fprisc
main =
  me = myself 0;
  p = Poller.start Unit;
  l = (case Tcp.listen "127.0.0.1" 0 of Ok x -> x | Err e -> error e);
  _ = spawn (fn self -> Tcp.serveOn p l (fn p conn ->
      case Stream.readLine (Stream.readerOn p conn) of
        (Err _, _) -> _ = Stream.close conn
      | (Ok line, r) ->
          if line == "bye" then _ = Stream.close conn
          else _ = Stream.write "{String.toUpper line}\n" conn;
          self r conn));
  _ = print "Server started on port {Tcp.port l}";
  Tcp.stop l;
  print "done".
```

