  |> List.map (fn g -> (cust, rs) = g;
    let total = List.sum (List.map (fn r -> unwrap (C.col "amount" r)) rs);
    let count = List.len rs;
    (cust, total, count));
summary = JArr (List.map (fn t -> (cust, total, count) = t;
    JObj [("customer", JStr cust), ("total", JNum total), ("avg", JNum (Numeric.div total count))])) totals);
```

