summary = JArr (List.map (fn t -> (cust, total) = t;
    n = List.len (List.filter (fn r -> C.col "customer" r == Ok cust) good);
    JObj [("customer", JStr cust), ("orders", JNum n), ("total", JNum total), ("avg", JNum (Numeric.div total n))]) totals);
```

