@arg key_code: u16
@arg key_value: u32
@arg timestamp: u64
@arg type_val: u16

load64 timestamp, r0
load16 type_val, r1
load16 key_code, r2
load32 key_value, r3

// Write the 24-byte record: 2x u64 (timestamp), u16 (type), u16 (code), u32 (value)
// Assuming buffer address is in r4
