```sol
main =
  granted = ("/services/display", "write")
         :: ("/services/clock", "read")
         :: Nil;
  caps = SVCM.Caps con me clk granted "svctest" (False, 0);
  _ = Svc.write caps "/services/display" (IStr "test message");
