```sol
spring : (k : Int | measure k) -> Int -> Int -> Int -> (List _, List _) .
spring k t x v | k <= 0 = ([], []).
spring k t x v =
  v2 = v + (0 - 4) * x * 0.05 - 0.3 * v * 0.05;
  x2 = x + v2 * 0.05;
