  const out = []; let code = false, buf = [], list = false;
  const flushList = () => \{ if (list) \{ out.push('</ul>'); list = false; } \};
  for (const raw of md.split('\\n')) \{
    // ... processing logic ...
    else if (/^[-*] /.test(l)) \{
      if (!list) \{ out.push('<ul>'); list = true; \}
      out.push('<li>' + inl(l.slice(2)) + '</li>');
    }
    else if (l.trim() === '') flushList();
    else \{ flushList(); out.push('<p>' + inl(l) + '</p>'); \}
  }
  return out.join('');
}
