// In ESP-IDF, the runtime directly configures the radio and handles interrupts
// without a process scheduler or virtual memory guard pages.

import "esp32";

@interrupt
proc on_rx_done() {
    // Directly access hardware registers or peripheral APIs
    radio_rx_buffer = read_reg(RADIO_RX_REG);
