hal/unix/gfx.c:
  // Request surfaceless EGL context
  context = eglCreateContext(surfaceless_platform);

  // Render scene to offscreen FBO
  fbo = create_offscreen_es31_fbo();
  render_scene_to(fbo);

  // Blit frame to monitor via raw DRM ioctls
  drm_scanout_blit(fbo_readback, target_crtc);
