let data = process reply;
// ... use data later ...
// Missing: drop reply;

// Correct: Drops immediately after forwarding/use
let reply = receiveFrom worker;
let data = process reply;
drop reply; // Ensures previous frame's reply is dropped and memory semantics are preserved
```

