You must use a pending object to store incoming values and a MutationObserver to trigger a fill function once the DOM elements appear. The script listens for 'live:set' events, stores the data in the pending object, and uses a MutationObserver watching the root element to iterate through pending values and assign them to elements matching the data-input attribute.

```sol
(function () {
  var pending = {};
  function fill() {
    Object.keys(pending).forEach(function (n) {
      var els = document.querySelectorAll('[data-input="' + n + '"]');
      if (!els.length) return;
      els.forEach(function (el) { el.value = pending[n]; el.dispatchEvent(new Event('input')); });
      delete pending[n];
    });
  }
  document.addEventListener('live:set', function (e) {
    var vals = JSON.parse(e.detail);
    Object.keys(vals).forEach(function (n) { pending[n] = vals[n]; });
    fill();
  });
  new MutationObserver(fill).observe(document.getElementById('lv-root'), { childList: true, subtree: true });
})();
```

The `fill` function iterates through pending values and queries the DOM for elements matching the `data-input` attribute. If an element exists, it sets the input value and dispatches an 'input' event to trigger UI updates; if the element is missing, the value remains in the `pending` object until the DOM updates.

```sol
(function () {
  var pending = {};
  function fill() {
    Object.keys(pending).forEach(function (n) {
      var els = document.querySelectorAll('[data-input="' + n + '"]');
      if (!els.length) return;
      els.forEach(function (el) { el.value = pending[n]; el.dispatchEvent(new Event('input')); });
      delete pending[n];
    });
  }
  document.addEventListener('live:set', function (e) {
    var vals = JSON.parse(e.detail);
    Object.keys(vals).forEach(function (n) { pending[n] = vals[n]; });
    fill();
  });
  new MutationObserver(fill).observe(document.getElementById('lv-root'), { childList: true, subtree: true });
})();
```

The value will be stored in the `pending` object and filled only after the element is created. This is because the script uses `MutationObserver` to watch for new elements; once an element with the matching `data-input` attribute appears in the DOM, the `fill()` function iterates through the `pending` object, sets the element's value, dispatches an `input` event, and then removes the key from `pending`.

```fprisc
