// Once the element is added (via MutationObserver), fill() executes and applies the value.
var pending = {};
document.addEventListener('live:set', function (e) {
  var vals = JSON.parse(e.detail);
  Object.keys(vals).forEach(function (n) { pending[n] = vals[n]; });
  fill(); // This runs immediately but waits for the element to exist inside fill()
});
```

