```sol
# Example: Initialize and turn on an OLED
init pinM pinW pins miso =
  Pins sck mosi cs dc = pins;
  _ = S.init pinM sck mosi cs miso;
  pinM dc 1;
  _ = cmd pinW pinR pins miso [initSeq];
