actor A = sendLinear actor B frame;
actor B = receive frame;
# B mutates frame, then sends it linearly to C
B = sendLinear actor C frame;
# C receives, uses frame, and sends it linearly back to A
C = receive frame;
C = sendLinear actor A frame;
# A receives, uses frame, and sends it linearly back to B
A = receive frame;
A = sendLinear actor B frame;
# Cycle completes with arcLive remaining constant at 1
```

