    tag 2 (replyTo, tag, url, payload) -> {
        replyTo, Ok, url, payload
    }

    // Tag 3: Replay all live records for a URL in log order
    tag 3 (replyTo, tag, url) -> {
        replyTo, Ok, replayAll(url)
    }
}
```

