func convert(tris, scale, floor) {
    out = []
    for t in tris {
        out.append([(x * scale, -y * scale, z * scale) for (x, y, z) in t])
    }
    if floor and out is not empty {
        lo = min(y for t in out for v in t)
        out = [[(x, y - lo, z) for (x, y, z) in t] for t in out]
    }
    return out
}
```

