// Pseudocode representing atomic operations in runtime/actors.c
actor send(msg: msg_t, target: actor_id_t) {
    if (target.is_in_limbo) {
        atomic_cas(&target.state, LIMBO, WAKE)
        atomic_fetch_add(&target.fuel, 1)
        send_signal(target, WAKE_EVENT)
    }
}
```

