  init = () -> {
    // Initialize scene
    return Scene2D()
  }
  update = (state, events) -> {
    // Effects and subscriptions are data returned here, not performed
    return {
      next_state = state,
      effects = []
    }
  }
  view = (scene) -> {
    // Returns the scene directly
    return scene
  }
}
```

Returning a `Scene` (such as `Scene2D`, `Scene3D`, or `None`) instead of a widget tree allows the MVU framework to model diverse application domains, including web apps, desktop apps, games, and headless remote services. This design choice enables a single architecture to cover all these cases uniformly, where `None` is used for services that do not render a visual scene.

```sol
