```fpr
# Portable UART RX handling: synchronous at message arrival
actor UART_Prt {
    # RX drains immediately upon receiving a message,
    # bypassing the interrupt-driven LSR.THRE check.
    UGet {
        # Reads RBR until LSR.DR clears, appends to buffer,
        # and pushes data downstream synchronously.
        let bytes := read_rx_until_dr_clear();
        push_to_subscribers(bytes);
        return UOkS bytes;
    }
}
```

