  _ = send parent (myPid 0, 7 * 6);
  0.

app me =
  shell = receiveFrom me;  -- Incorrect: expects two ports, blocks forever
  h = spawn (helper me);
  (hp, r) = receiveFrom me h;
  _ = send shell ("appb", myPid 0, hp, r);
  0.
```

