The script identifies its own processes by checking if the command associated with a given PID is "liveboard". It then groups these processes into a job and sends a SIGKILL signal to terminate them.

```python
def _looks_like_ours(pid):
    r = subprocess.run(['ps', '-o', 'command=', '-p', str(pid)], capture_output=True, text=True)
    return 'liveboard' in r.stdout

def _sweep():
    if not PIDFILE.exists():
        return
    killed = 0
    for tok in PIDFILE.read_text().split():
        if not tok.isdigit():
            continue
        pid = int(tok)
        if _looks_like_ours(pid):
            try:
                os.killpg(os.getpgid(pid), signal.SIGKILL)
                killed += 1
            except OSError:
                pass
    PIDFILE.unlink(missing_ok=True)
```

