machine.virt {
  architecture: rv64;
  components {
    tcp_stack: {
      connections: 4;
      table: [conn1, conn2, conn3, conn4];
    };
    block_driver: {};
    pin_bus: {};
  };
  interrupt_routing {
    max_irqs: 1024;
    plic_ceiling: 1024;
  };
}
```

