The WCET bound is calculated by summing the instruction costs of all basic blocks, adding the product of entry counts and the fuel-check constant, including the worst-case entry-point bounds for every called function, and adding the total promotion bounds for sends plus the total decref bounds for receives.

```sol
fun WCET_Bound(segment: Actor_Segment) -> Cost {
    var total_cost = 0
    // Sum over basic blocks of instruction cost
    for block in segment.basic_blocks {
        total_cost += block.instruction_cost
    }
    // Entries x fuel-check constant
    total_cost += segment.entry_count * FUEL_CHECK_CONSTANT
    // Sum over C calls of C-entry-point bound
    for call in segment.calls {
        total_cost += call.entry_point_bound
    }
    // Sends x promotion bound + recvs x decref bound
    total_cost += segment.send_count * PROMOTION_BOUND
    total_cost += segment.recv_count * DECREF_BOUND
    return total_cost
}
```

