    delete pending[n];
  });
}
new MutationObserver(fill).observe(document.getElementById('lv-root'), { childList: true, subtree: true });
```

This expression returns a NodeList containing all DOM elements within the observed subtree that have the `data-input` attribute set to the value of `n`. If no matching elements exist, it returns an empty NodeList. In the provided script, this result is checked with `!els.length` to ensure the script only attempts to update values when the corresponding input element has been created by the DOM.

```sol
var els = document.querySelectorAll('[data-input="' + n + '"]');
if (!els.length) return;
```

The `fill` function iterates over keys in the `pending` object to locate DOM elements matching the attribute `data-input` and assigns their corresponding values from the `pending` object. It also dispatches an `input` event on each populated element to trigger the associated UI logic. The function takes no arguments and relies on the `pending` object, which is defined within the enclosing scope.

```sol
function fill() {
