// This demonstrates the separation of the host environment and the app runtime
program main_qa:
    import "qos/x86_64/runtime"
    import "qos/std"

    // The app code runs here, unaware of the host's libc or socket implementation
    // It relies on the QOS Portable runtime to bridge the gap.
    func run():
        print "Hello from QOS Portable"
    end

    // Entry point for the QAR1 archive
    entry:
        call run
    end
```

