```sol
// Example: Instead of sending the whole model `cart` to every actor,
// send a diff `delta` that updates the local state.
actor session {
  model cart: CartModel;
  send delta: {
    // Only the delta is sent over the wire.
    cart = cart + delta; 
  };
}
```

