    a + b
}

// Full FP-RISC goal (ownership-aware PAPs and lifted functions)
fn process_data(data: Arc<RefCell<Vec<u8>>>) -> u32 {
    // Requires ownership-aware PAPs and indirect application
    data.borrow().len() as u32
}
```

