func on_enemy_attack(attacker, target, overwatch_unit, column_diff) {
    if (abs(column_diff) <= 1 && overwatch_unit.is_in_overwatch) {
        let intercept_damage = floor(attacker.atk * 0.5)
        attacker.take_damage(intercept_damage)
        if (attacker.alive) {
