  m2 = { m | screen = scrPause, menu = 0, confirm = 0 };
  _ = sndMusic musicFile (volNow m2);
  (cue (note m2 "paused") Sfx.toggle, Nil).

resume m =
  m2 = { m | screen = scrPlay, msg = "" };
  _ = sndMusic musicFile (volNow m2);
  m2.

