To launch an application, call `lLaunch` with the file system, message ID, command chain, source ID, and application ID. The system reads the latest `.qa` file for that ID, attaches the plug to get a new process ID, detaches the registry, and spawns the app via `Sys.spawnApp`. Once spawned, the host gate sends the new process ID back to the caller.

```fpr
lLaunch fs me chain from id =
  r = FS.readLatest me fs "apps/{id}.qa";
  case r of
    Err e -> send from (Err "launch {id}: {e}") >> lLoop fs me chain
  | Ok qa ->
      ar = Plug.attach qa;
      case ar of
        Err e -> send from (Err "launch {id}: {e}") >> lLoop fs me chain
      | Ok n ->
          (ok, f) = Mod.findAt (Mod.plugs 0 - 1) "app";
          case ok == 1 of
            True ->
              h = Sys.spawnApp f;
              _ = AC.sendOrDie h from;
              _ = send from (Ok h);
              lLoop fs me chain
          | False -> send from (Err "launch {id}: no `app` export") >> lLoop fs me chain
```

