  var buffer = Sys.alloc(1024);
  // buffer grows forever; no reset called
}

// Correct: Reclaiming memory at loop boundaries
actor worker {
  var temp = Sys.alloc(1024);
  loop {
    // process temp
    Sys.poolReset(); // Reclaims temp storage
  }
}
```

