You can extract this value using the following Python code:

```python
def load_sha_of(qa_path):
    with open(qa_path, "rb") as f:
        b = f.read()
    if b[:5] != b"QAR2\n":
        raise SystemExit(f"not a QAR2 archive")
    head, _, _ = b.partition(b"\n\n")
    off = len(head) + 2
    for line in head.decode().split("\n")[1:]:
        name, o, n = line.split()
        if name == "LOAD":
            load = b[off + int(o) : off + int(o) + int(n)].decode()
            for ln in load.split("\n"):
                if ln.startswith("sha "):
                    return ln.split()[1]
    raise SystemExit(f"no LOAD sha found")
```

