The QOS system utilizes a custom WebSocket protocol where the server sends frames containing either a full snapshot or incremental updates to a client's program state. The client parses incoming frames to reconstruct the program's state, specifically tracking the source (`s`) and destination (`d`) arrays, which must always remain equal in length plus one. When a frame indicates a partial update (`p=2` or `p=3`), the client performs a merge operation to update the current state based on the start, removal, and insertion logic provided in the message.

```sol
@module ws_handler
import json, struct

func handle_frame(msg: dict):
    if msg.p == 2:
        // Merge single update into current state
        for field in ['s', 'd']:
            old := state[field]
            start, remove, insert := msg[field]
            state[field] := old[:start] + insert + old[start+remove]
    else if msg.p == 3:
        // Merge list of updates into current state
        for field in ['s', 'd']:
            cur := state[field]
            for update in msg[field]:
                start, remove, insert := update
                cur := cur[:start] + insert + cur[start+remove]
            state[field] := cur
```

